/**
 * Google Fonts: the bundled catalogue and the rules every font choice obeys.
 *
 * The catalogue (google-fonts.json, ~1,900 families, regenerated by
 * scripts/google-fonts-catalog.ts) lists each family's category, weights and
 * whether it has italics, most popular first. Nothing at runtime asks Google
 * what exists: a family is valid when it is in this file.
 *
 * Fonts are never loaded from Google by a visitor's browser. Pages link our
 * own stylesheet, `/fonts/g/<slug>/<weights>.css` (app/fonts/g/…), which the
 * server fetches from fonts.googleapis.com once, rewrites to our own font
 * file URLs and keeps in the storage provider (lib/fonts/serve.ts). With
 * remote fetching off (air-gapped installs: FONTS_REMOTE=off) only fonts
 * already stored load; everything else falls back to the family's category
 * stack, so text always renders.
 *
 * Family names are limited to [A-Za-z0-9 -] (the generator drops anything
 * else), so a family quoted in CSS or put in a URL can't break out of it.
 * Pure and isomorphic.
 */

import catalog from './google-fonts.json'

export const GOOGLE_FONT_CATEGORIES = ['sans', 'serif', 'display', 'handwriting', 'mono'] as const
export type GoogleFontCategory = (typeof GOOGLE_FONT_CATEGORIES)[number]
export const GOOGLE_FONT_CATEGORY_LABELS: Record<GoogleFontCategory, string> = {
  sans: 'Sans serif', serif: 'Serif', display: 'Display', handwriting: 'Handwriting', mono: 'Monospace',
}

const CATEGORY_CODES: Record<string, GoogleFontCategory> = { s: 'sans', r: 'serif', d: 'display', h: 'handwriting', m: 'mono' }

/** What a family falls back to while it loads, or when it can't (remote fetching off, offline). */
export const GOOGLE_FONT_FALLBACK: Record<GoogleFontCategory, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif',
  serif: 'ui-serif, Georgia, Cambria, "Times New Roman", Times, serif',
  display: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Arial, sans-serif',
  handwriting: '"Segoe Print", "Bradley Hand", "Comic Sans MS", cursive',
  mono: 'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace',
}

/** Families the app already ships through next/font (app/layout.tsx): drawn from the bundle, never fetched. */
export const BUNDLED_GOOGLE_FONTS: Record<string, '--font-sans' | '--font-mono' | '--font-display'> = {
  Inter: '--font-sans',
  'JetBrains Mono': '--font-mono',
  Fraunces: '--font-display',
}

export interface GoogleFont {
  family: string
  /** URL form: lower case, runs of other characters → `-` ("Source Sans 3" → `source-sans-3`). */
  slug: string
  category: GoogleFontCategory
  /** Upright weights Google serves (100–900). */
  weights: number[]
  /** Italic weights (empty: no italics). */
  italics: number[]
  /** next/font variable when the app bundles the family. */
  bundledVar?: '--font-sans' | '--font-mono' | '--font-display'
}

export const GOOGLE_FONT_FAMILY_RE = /^[A-Za-z0-9][A-Za-z0-9 -]{0,63}$/
const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/

export function googleFontSlug(family: string): string {
  return family.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
}

let fonts: GoogleFont[] | null = null
let byName: Map<string, GoogleFont> | null = null
let bySlug: Map<string, GoogleFont> | null = null

/** Every family, most popular first. */
export function googleFonts(): GoogleFont[] {
  if (fonts) return fonts
  const rows = (catalog as unknown as { fonts: Array<[string, string, number, number]> }).fonts
  const bits = (mask: number) => {
    const out: number[] = []
    for (let i = 0; i < 9; i++) if (mask & (1 << i)) out.push((i + 1) * 100)
    return out
  }
  fonts = rows.map(([family, code, upright, italic]) => {
    const bundledVar = BUNDLED_GOOGLE_FONTS[family]
    return { family, slug: googleFontSlug(family), category: CATEGORY_CODES[code] ?? 'sans', weights: bits(upright), italics: bits(italic), ...(bundledVar ? { bundledVar } : {}) }
  })
  byName = new Map(fonts.map((f) => [f.family.toLowerCase(), f]))
  bySlug = new Map(fonts.map((f) => [f.slug, f]))
  return fonts
}

/** A family by name (case and surrounding space ignored), or undefined when Google Fonts has no such family. */
export function findGoogleFont(name: unknown): GoogleFont | undefined {
  if (typeof name !== 'string') return undefined
  const clean = name.trim().replace(/\s+/g, ' ')
  if (!GOOGLE_FONT_FAMILY_RE.test(clean)) return undefined
  googleFonts()
  return byName!.get(clean.toLowerCase())
}

export function findGoogleFontBySlug(slug: unknown): GoogleFont | undefined {
  if (typeof slug !== 'string' || !SLUG_RE.test(slug)) return undefined
  googleFonts()
  return bySlug!.get(slug)
}

/** CSS font-family for a family: its bundled variable or quoted name, then its category's fallback stack. */
export function googleFontStack(font: GoogleFont, fallback?: string): string {
  const tail = fallback ?? GOOGLE_FONT_FALLBACK[font.category]
  return font.bundledVar ? `var(${font.bundledVar}), ${tail}` : `'${font.family}', ${tail}`
}

/** The nearest weights the family has, sorted and de-duplicated (Google rejects a request for a missing one). */
export function snapGoogleWeights(font: Pick<GoogleFont, 'weights'>, wanted: readonly number[]): number[] {
  const out = new Set<number>()
  for (const w of wanted.length ? wanted : [400]) {
    let best = font.weights[0]
    for (const c of font.weights) if (Math.abs(c - w) < Math.abs(best - w)) best = c
    out.add(best)
  }
  return [...out].sort((a, b) => a - b)
}

/**
 * The variant part of a family's stylesheet URL: its upright and italic
 * weights as bitmasks (`w1ff`, `w1ff-i1ff`). One stylesheet per family holds
 * all of its faces — a browser only downloads the faces a page actually
 * uses — so a family has exactly one URL (one cache entry, one upstream
 * fetch, one thing to pre-seed), and the URL changes when the catalogue's
 * weights for it do.
 */
export function googleFontVariant(font: Pick<GoogleFont, 'weights' | 'italics'>): string {
  const mask = (ws: number[]) => ws.reduce((m, w) => m | (1 << (w / 100 - 1)), 0).toString(16)
  return `w${mask(font.weights)}${font.italics.length ? `-i${mask(font.italics)}` : ''}`
}

/** Whether a URL's variant is the family's (anything else is a 404: no cache-key or upstream fan-out). */
export function isGoogleFontVariant(font: GoogleFont, variant: unknown): boolean {
  return typeof variant === 'string' && variant === googleFontVariant(font)
}

/** Where our stylesheets live (app/fonts/g/[family]/[variant]/route.ts). */
export const GOOGLE_FONT_ROUTE = '/fonts/g'

/** Our stylesheet for a family, or null for unknown / bundled families. */
export function googleFontHref(family: string | GoogleFont | null | undefined): string | null {
  const font = typeof family === 'string' ? findGoogleFont(family) : family
  if (!font || font.bundledVar) return null
  return `${GOOGLE_FONT_ROUTE}/${font.slug}/${googleFontVariant(font)}.css`
}

/** One stylesheet per family for a list of families (unknown and bundled ones skipped), in first-use order. */
export function googleFontHrefs(families: ReadonlyArray<string | null | undefined>): string[] {
  const out: string[] = []
  for (const family of families) {
    const href = family ? googleFontHref(family) : null
    if (href && !out.includes(href)) out.push(href)
  }
  return out
}
